-- =====================================================================
-- BreachLab - две подсказки к каждому заданию (уже применено в проекте)
-- Подсказка 1 стоит 2 очка, подсказка 2 (подробная) - 3 очка.
-- =====================================================================
alter table public.tasks add column if not exists hint2 text;
alter table public.tasks add column if not exists has_hint2 boolean generated always as (hint2 is not null) stored;
grant select (has_hint2) on public.tasks to anon, authenticated;
alter table public.hint_unlocks add column if not exists level smallint not null default 1 check (level in (1, 2));
-- Функции unlock_hint(task, level), room_hints(room) и submit_answer обновлены в миграции two_level_hints.

update public.tasks t set hint = v.h1, hint2 = v.h2 from public.rooms r, (values
('welcome',1,'Флаг прямо в тексте теории этой комнаты.','Прокрутите теорию до самого конца: флаг стоит в последней строке и начинается с BL{hello_…}.'),
('welcome',2,'Об этом сказано в абзаце про очки.','В теории написано, что очки начисляются за каждое задание «… раз». Ответ - число меньше двух.'),
('welcome',3,'Вспомните правило платформы в жёлтой рамке.','Проверять чужие системы можно только с письменного разрешения владельца. Без разрешения это незаконно.'),
('cia-triad',1,'Подумайте, какое свойство страдает, когда сервис просто не работает.','DDoS не крадёт и не меняет данные, он делает сайт недоступным. Ищите свойство про работу сервиса «когда он нужен».'),
('cia-triad',2,'Утечка - это когда данные увидели те, кому не положено.','Свойство отвечает за то, чтобы данные видели только те, кому положено. Английское название начинается на C.'),
('cia-triad',3,'Данные не украли, а подменили.','Свойство про то, что данные не изменены незаметно. Английская буква триады - I.'),
('cia-triad',4,'Резервные копии нужны, чтобы данные можно было вернуть и продолжить работу.','Бэкапы защищают от ситуации «данные пропали и сервис встал». Это то же свойство, что страдает от DDoS.'),
('soc-intro',1,'Посмотрите таблицу «Линии аналитиков».','Линий три: L1, L2 и L3. Первую очередь алертов разбирает самая младшая линия.'),
('soc-intro',2,'В теории есть раздел «Как оценивают алерт».','Алерт есть, а атаки нет. Второе слово - positive, а первое означает «ложный» по-английски.'),
('soc-intro',3,'Это «самое опасное» из списка оценок алертов.','Атака была, а алерта нет. Первое слово - false, второе противоположно слову positive.'),
('soc-intro',4,'Смотрите таблицу кодов событий Windows.','Успешный вход - 4624. Неудачная попытка идёт следующим номером.'),
('soc-intro',5,'Код есть в той же таблице событий Windows.','Код начинается на 47 и заканчивается на 0.'),
('soc-intro',6,'Расшифровка есть в разделе «Индикаторы компрометации».','Indicator of … Последнее слово означает «компрометация» по-английски.'),
('network-basics',1,'Посмотрите таблицу портов.','У HTTP порт 80, а у шифрованного HTTPS - трёхзначный номер, начинается на 4.'),
('network-basics',2,'Порт удалённого управления сервером есть в таблице.','Это двузначное число, на единицу больше порта FTP (21).'),
('network-basics',3,'Протокол упомянут в последнем разделе теории.','Это аббревиатура из трёх букв: Domain Name System.'),
('network-basics',4,'Смотрите раздел «Рукопожатие TCP».','Клиент отвечает «подтверждаю». Это вторая часть слова SYN-ACK.'),
('network-basics',5,'Сверьтесь со списком частных диапазонов IPv4.','Один из частных диапазонов - 192.168.0.0-192.168.255.255. Попадает ли в него 192.168.1.10?'),
('network-basics',6,'Найдите порт 3389 в таблице портов.','Это удалённый рабочий стол Windows: Remote Desktop Protocol, три буквы.'),
('network-basics',7,'Смотрите раздел «TCP и UDP».','TCP заново отправляет потерянные пакеты. Второй протокол так не делает и поэтому быстрее.'),
('linux-basics',1,'Команда есть в первой строке таблицы команд.','Это сокращение от print working directory, три буквы.'),
('linux-basics',2,'В таблице команд есть пример с auth.log.','Команда из четырёх букв, начинается на g: она ищет строки с нужным текстом.'),
('linux-basics',3,'Смотрите раздел «Важные места».','Путь начинается с /var/ и заканчивается словом, которое значит «журнал».'),
('linux-basics',4,'Смотрите раздел «Важные места».','Файл лежит в папке /etc/ и называется словом, которое по-английски значит «пароль», но без двух букв o и r.'),
('linux-basics',5,'Каждая тройка символов даёт одну цифру: r=4, w=2, x=1.','rw- = 4+2 = 6, а r-- = 4. Права записаны тройками: владелец, группа, остальные.'),
('linux-basics',6,'Это главный пользователь, о нём сказано в конце теории.','Его имя - четыре буквы, по-английски значит «корень».'),
('linux-basics',7,'Ключ есть в таблице команд рядом с grep.','Ключ из одной буквы - первой буквы слова count.'),
('encoding-hashes',1,'Откройте страницу «Инструменты».','Выберите «Base64 → раскодировать» и вставьте строку целиком, со знаками == на конце. Результат начнётся с BL{base64_…}.'),
('encoding-hashes',2,'Hex - это две цифры 0-9 или a-f на каждый символ.','В «Инструментах» выберите «Hex → раскодировать». Первые байты 42 4c 7b - это BL{.'),
('encoding-hashes',3,'ROT13 сдвигает каждую латинскую букву на 13.','В «Инструментах» выберите ROT13. OY превращается в BL, а знаки { } _ и цифры не меняются.'),
('encoding-hashes',4,'Смотрите список хешей в конце теории.','MD5 - 32 символа, SHA-1 - 40. SHA-256 длиннее обоих, это 256 бит / 4 бита на hex-символ.'),
('encoding-hashes',5,'Посмотрите таблицу «Три разных вещи».','Хеш - это «отпечаток», из него нельзя вернуть исходный текст.'),
('encoding-hashes',6,'Длина 32 hex-символа есть в списке хешей.','Из списка: SHA-1 - 40 символов, SHA-256 - 64. Остаётся самый старый алгоритм.'),
('encoding-hashes',7,'В «Инструментах» есть SHA-256.','Введите breachlab строчными, без пробелов. Ответ - первые 8 символов результата, он начинается на 6c59.'),
('web-basics',1,'Откройте учебный сайт и нажмите Ctrl+U.','Комментарий стоит в самом начале кода, сразу после <body>, и начинается со слов «TODO: убрать перед релизом».'),
('web-basics',2,'Cookie видно в инструментах разработчика.','F12 → Application (Приложение) → Cookies. Имя cookie - promo, значение начинается с BL{cookies_…}.'),
('web-basics',3,'Откройте rooms/web-basics/robots.txt.','В строке Disallow есть путь /hidden-panel/. Добавьте его к адресу папки: rooms/web-basics/hidden-panel/.'),
('web-basics',4,'Пароль проверяет JavaScript на странице.','Откройте файл rooms/web-basics/lab.js: там переменная SECRET, её значение и есть ответ.'),
('web-basics',5,'Смотрите таблицу кодов HTTP.','Коды 4xx - ошибки клиента: 403 значит «запрещено», а «не найдено» стоит рядом.'),
('web-basics',6,'Смотрите раздел «Методы HTTP».','GET показывает параметры в адресе, поэтому форму входа отправляют вторым методом из четырёх букв.'),
('phishing-email',1,'Откройте .eml в Блокноте, заголовок в первой строке.','Домен после @ в Return-Path: в нём вместо буквы o стоит цифра 0, начинается с n0rdbank-…'),
('phishing-email',2,'Ищите заголовок Received.','IP стоит в квадратных скобках после «unknown» и начинается на 198.51.'),
('phishing-email',3,'Смотрите заголовок Authentication-Results.','Там строка вида spf=… Ответ - одно слово после знака =.'),
('phishing-email',4,'Ищите заголовок Reply-To.','В Reply-To указан адрес на бесплатной почте. Ответ - часть после @, заканчивается на .example.'),
('phishing-email',5,'Ссылка есть в тексте письма.','Ссылка начинается с https://. Нужен только домен - часть до первого /, он начинается с nordbank-…'),
('phishing-email',6,'Посмотрите имя файла вложения.','У вложения два расширения. Настоящее - последнее, оно запускает программу в Windows.'),
('phishing-email',7,'Вложение - это текст в Base64 в конце письма.','Скопируйте две строки после «Content-Transfer-Encoding: base64» и раскодируйте в «Инструментах». Флаг будет в конце текста.'),
('log-analysis',1,'Ищите строки Failed password.','Один адрес повторяется там сотни раз. Он из диапазона для документации 203.0.113.x.'),
('log-analysis',2,'Посчитайте строки Failed password только с этим IP.','PowerShell: (Select-String -Path auth.log -Pattern "Failed password.*203.0.113.45").Count - число больше 100.'),
('log-analysis',3,'Ищите строку Accepted password с того же IP.','Строка выглядит как «Accepted password for ИМЯ from 203.0.113.45». Нужно имя пользователя.'),
('log-analysis',4,'Время стоит в начале строки успешного входа.','Найдите «Accepted password … 203.0.113.45». Вход был в четвёртом часу ночи, ответ вида 03:ММ:СС.'),
('log-analysis',5,'Ищите строки со словом useradd.','В строке useradd есть «new user: name=…». Имя похоже на системное обновление.'),
('log-analysis',6,'Посмотрите команду usermod в строках sudo.','Ключ -aG добавляет пользователя в группу. Группа администраторов в Linux называется так же, как команда для запуска от root.'),
('log-analysis',7,'Поищите Brute Force на attack.mitre.org.','Номер начинается на T11 и состоит из T и четырёх цифр. Подтехники пишутся через точку, а нужна основная техника.'),
('crypto-2',1,'Слоёв три. Первый - Base64.','После Base64 получится hex (цифры и a-f), после hex - текст вида OY{…}. Последний слой - ROT13.'),
('crypto-2',2,'Флаг начинается с B, а его код 0x42.','Ключ = первый байт шифра XOR 0x42 = 0x68 XOR 0x42. Посчитайте побитово: 0110 1000 XOR 0100 0010.'),
('crypto-2',3,'В «Инструментах» есть XOR с ключом.','Выберите «XOR (hex + ключ)», вставьте весь шифр и введите ключ из прошлого задания: 2a.'),
('crypto-2',4,'Вариантов сдвига всего 25.','В «Инструментах» выберите «Цезарь: все сдвиги» и найдите строку, которая начинается с BL{. Сдвиг больше 15.'),
('crypto-2',5,'Хеш нельзя расшифровать, но можно сравнить.','Вставьте весь wordlist.txt в «SHA-256 каждой строки» и найдите через Ctrl+F начало хеша 49eff747. Слово связано с погодой.'),
('crypto-2',6,'Посчитайте длину хеша.','В хеше 40 hex-символов. MD5 - 32, SHA-256 - 64.'),
('crypto-2',7,'Об этом сказано в разделе про подбор хеша по словарю.','Слово из четырёх букв, как приправа на кухне. По-английски salt.'),
('osint-basics',1,'OSINT - Open Source Intelligence.','Open Source здесь значит «открытые источники». Нужно одно слово: разведка по … источникам.'),
('osint-basics',2,'Смотрите раздел «О нас» на сайте кофейни.','Там сказано, где главный офис и обжарочный цех. Город на Волге, улица Баумана.'),
('osint-basics',3,'Посмотрите, как устроены адреса коллег.','У коллег адреса вида имя.фамилия@coffee-byte.example латиницей. Мария Иванова - maria и …'),
('osint-basics',4,'Откройте страницу вакансии.','В списке обязанностей есть пункт про удалённый доступ. Название программы начинается на Open…'),
('osint-basics',5,'Откройте страницу вакансии.','Последний пункт обязанностей - про поддержку сайта. Самый популярный в мире движок для сайтов.'),
('osint-basics',6,'Описание фото видно только в коде страницы.','Нажмите Ctrl+U и найдите aria-label у фото. Там написано про стикер: «пароль Coffee…».'),
('osint-basics',7,'Подумайте, что устранит утечку быстрее всего.','Пароль уже видели посторонние. Его нужно поменять, а фото убрать. Удалять весь сайт незачем.'),
('windows-basics',1,'Сочетание есть в разделе «Процессы и службы».','Три клавиши: Ctrl, Shift и клавиша в левом верхнем углу клавиатуры.'),
('windows-basics',2,'Смотрите раздел «Процессы и службы».','Такие программы видно в services.msc. Одно слово, по-английски service.'),
('windows-basics',3,'Путь есть в абзаце про svchost.exe.','Путь начинается с C:\Windows\. Дальше папка System и число разрядности.'),
('windows-basics',4,'Смотрите раздел «Журналы событий».','Журналов три: Безопасность, Система, Приложение. Входы и учётные записи относятся к безопасности.'),
('windows-basics',5,'Смотрите таблицу команд PowerShell.','Команды строятся как Глагол-Существительное: Get-Process для процессов, а для служб …'),
('windows-basics',6,'Команда есть в разделе «Журналы событий».','Это сокращённое event viewer (часть букв выброшена) с окончанием .msc, как у services.msc.'),
('windows-basics',7,'Сверьтесь с таблицей «Автозагрузка».','Ключ Run, Планировщик и папка «Автозагрузка» есть в таблице. Лишний вариант - место для удалённых файлов.'),
('passwords-2fa',1,'Формула: E = L × log₂(N).','L = 10, N = 26, а log₂(26) ≈ 4,70. 10 × 4,70 = … Округлите до целого.'),
('passwords-2fa',2,'Атака описана в разделе «Как ломают пароли».','Первое слово - credential («учётные данные»), второе значит «набивка», начинается на stuff…'),
('passwords-2fa',3,'Вспомните: длина важнее сложности.','Фраза из четырёх случайных слов длиннее и не входит в словари утечек, в отличие от P@ssw0rd! и Qwerty123.'),
('passwords-2fa',4,'Смотрите раздел про TOTP.','Код из приложения-аутентификатора состоит из цифр, их больше пяти, но меньше семи.'),
('passwords-2fa',5,'Смотрите раздел про TOTP.','Код меняется два раза в минуту.'),
('passwords-2fa',6,'Список идёт от слабого к сильному.','Этот фактор сам проверяет адрес сайта, поэтому фишинговый сайт его не обманет. Это физическое устройство.'),
('passwords-2fa',7,'Смотрите раздел «Как сайты должны хранить пароли».','MD5 и SHA-1 слишком быстрые и устарели, а Base64 вообще не хеш. Нужна медленная функция из теории.'),
('incident-response',1,'Смотрите раздел «Сдерживание - первым делом».','Главное - не дать вирусу распространиться дальше. Выключать компьютер как раз не нужно.'),
('incident-response',2,'Это первый этап NIST.','На этом этапе всё делают заранее, до инцидента. Одно слово на «П».'),
('incident-response',3,'Ответ есть в разделе про сдерживание.','Всё, что лежит в оперативной памяти, пропадёт при выключении. А там следы, нужные расследованию.'),
('incident-response',4,'Смотрите раздел «Шифровальщики».','Нет гарантии, что файлы вернут, а злоумышленники получат деньги на новые атаки.'),
('incident-response',5,'Вспомните правило 3-2-1.','Первая цифра правила - сколько копий, вторая - сколько типов носителей, третья - сколько копий вне офиса.'),
('incident-response',6,'Смотрите таблицу этапов, четвёртый этап.','Разбор ошибок по-английски: lessons … Второе слово значит «выученные».'),
('incident-response',7,'Смотрите таблицу этапов NIST.','Этот этап идёт после обнаружения и анализа. Его название состоит из трёх слов через запятую.')
) as v(slug, pos, h1, h2) where r.id = t.room_id and r.slug = v.slug and t.position = v.pos;
